#include <bits/stdc++.h>

using namespace std;

bool att(const string &a, const string &b, const string &c) {
    if (a[0] == c[0]) {
        if (b[0] != c[0]) {
            return true;
        }
        if (a[1] < c[1] && (b[1] <= a[1] || c[1] <= b[1])) {
            return true;
        }
        if (a[1] > c[1] && (b[1] >= a[1] || c[1] >= b[1])) {
            return true;
        }
    }
    if (a[1] == c[1]) {
        if (b[1] != c[1]) {
            return true;
        }
        if (a[0] < c[0] && (b[0] <= a[0] || c[0] <= b[0])) {
            return true;
        }
        if (a[0] > c[0] && (b[0] >= a[0] || c[0] >= b[0])) {
            return true;
        }
    }
    return false;
}

bool check(const string &kb, const string &r0, const string &r1, const string &kw) {
    if (kb[0] < 'a' || kb[0] > 'h') {
        return false;
    }
    if (kb[1] < '1' || kb[1] > '8') {
        return false;
    }

    if (kb != r0) {
        if (att(kb, r1, r0) && att(kb, kw, r0)) {
            return false;
        }
    }
    if (kb != r1) {
        if (att(kb, r0, r1) && att(kb, kw, r1)) {
            return false;
        }
    }
    if (kb != kw) {
        if (kw[0] - 1 <= kb[0] && kb[0] <= kw[0] + 1 &&
            kw[1] - 1 <= kb[1] && kb[1] <= kw[1] + 1) {
            return false;
        }
    }
    return true;
}

